export const findPokemon = (id: string) => POKEMON.find((p) => p.id === id);

export const NATURES = [
  "Hardy","Lonely","Brave","Adamant","Naughty",
  "Bold","Docile","Relaxed","Impish","Lax",
  "Timid","Hasty","Serious","Jolly","Naive",
  "Modest","Mild","Quiet","Bashful","Rash",
  "Calm","Gentle","Sassy","Careful","Quirky",
] as const;
export type Nature = typeof NATURES[number];

export const EV_TOTAL_CAP = 510;
export const EV_INDIVIDUAL_CAP = 252;

export const calcHp = (base: number, iv: number, ev: number, level: number) =>
  Math.floor(((2 * base + iv + Math.floor(ev / 4)) * level) / 100) + level + 10;

export const calcStat = (base: number, iv: number, ev: number, natureMod: number) =>
  Math.floor((Math.floor(((2 * base + iv + Math.floor(ev / 4)) * 50) / 100) + 5) * natureMod);

const SPEED_PLUS: Nature[] = ["Timid","Hasty","Jolly","Naive"];
const SPEED_MINUS: Nature[] = ["Brave","Relaxed","Quiet","Sassy"];
export const speedNatureMod = (n: Nature): number =>
  SPEED_PLUS.includes(n) ? 1.1 : SPEED_MINUS.includes(n) ? 0.9 : 1.0;
